import React, { useEffect, useState } from 'react';
import api from '@/lib/api';

export default function LotesProveedorPage() {
  const [rows, setRows] = useState([]);
  const [claims, setClaims] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  async function loadData() {
    setLoading(true);
    setError('');
    try {
      const lotesRes = await api.get('/tablajeria/lotes-proveedor/rendimientos?limit=100&offset=0');
      const reclamosRes = await api.get('/tablajeria/reclamos-proveedor?limit=100');
      setRows(lotesRes.data && lotesRes.data.rendimientos ? lotesRes.data.rendimientos : []);
      setClaims(reclamosRes.data && reclamosRes.data.reclamos ? reclamosRes.data.reclamos : []);
    } catch (err) {
      setError('No fue posible cargar lotes proveedor.');
    } finally {
      setLoading(false);
    }
  }

  useEffect(function init() {
    loadData();
  }, []);

  function fmt(value) {
    const n = Number(value || 0);
    return n.toLocaleString('es-MX', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }

  return (
    <div className="p-6 space-y-6" data-testid="tablajeria-lotes-proveedor">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold">Lotes proveedor</h1>
          <p className="text-sm text-muted-foreground">Rendimiento, desviaciones, impacto economico y reclamos por lote de compra.</p>
        </div>
        <button className="px-4 py-2 rounded border text-sm" type="button" onClick={loadData} disabled={loading}>Actualizar</button>
      </div>
      {error ? <div className="p-4 rounded bg-red-50 text-red-700">{error}</div> : null}
      <div className="bg-white rounded-lg border overflow-hidden">
        <div className="px-4 py-3 border-b"><h2 className="font-semibold">Rendimientos por lote</h2></div>
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="bg-gray-50"><tr><th className="text-left p-3">Lote</th><th className="text-left p-3">Proveedor</th><th className="text-right p-3">Rendimiento</th><th className="text-right p-3">Desviacion</th><th className="text-right p-3">Impacto</th><th className="text-left p-3">Semaforo</th></tr></thead>
            <tbody>
              {rows.map(function rowView(row, index) {
                return <tr key={row.LoteRendimientoID || index} className="border-t"><td className="p-3">{row.LoteProveedor || row.LoteInterno || '-'}</td><td className="p-3">{row.ProveedorNombre || '-'}</td><td className="p-3 text-right">{fmt(row.RendimientoRealPorcentaje)}%</td><td className="p-3 text-right">{fmt(row.DesviacionPorcentaje)}%</td><td className="p-3 text-right">${fmt(row.ImpactoEconomico)}</td><td className="p-3">{row.Semaforo || 'SIN_DATOS'}</td></tr>;
              })}
              {!rows.length && !loading ? <tr><td className="p-6 text-center text-muted-foreground" colSpan="6">Sin registros.</td></tr> : null}
            </tbody>
          </table>
        </div>
      </div>
      <div className="bg-white rounded-lg border overflow-hidden">
        <div className="px-4 py-3 border-b"><h2 className="font-semibold">Reclamos proveedor</h2></div>
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="bg-gray-50"><tr><th className="text-left p-3">Folio</th><th className="text-left p-3">Proveedor</th><th className="text-left p-3">Motivo</th><th className="text-left p-3">Estatus</th><th className="text-right p-3">Impacto</th></tr></thead>
            <tbody>
              {claims.map(function claimView(claim, index) {
                return <tr key={claim.ReclamoProveedorID || index} className="border-t"><td className="p-3">{claim.FolioReclamo || '-'}</td><td className="p-3">{claim.ProveedorNombre || '-'}</td><td className="p-3">{claim.Motivo || '-'}</td><td className="p-3">{claim.Estatus || '-'}</td><td className="p-3 text-right">${fmt(claim.ImpactoEconomico)}</td></tr>;
              })}
              {!claims.length && !loading ? <tr><td className="p-6 text-center text-muted-foreground" colSpan="5">Sin reclamos.</td></tr> : null}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
